mapper.select:
SELECT REG_DT
  FROM EML_CERT
 WHERE CERT_TRGT_EML_HMAC = #{certTrgtEmlHmac}
   AND EML_CERT_PRPS_CD = #{emlCertPrpsCd}
   AND REG_DT >= #{since}
 ORDER BY REG_DT, EML_CERT_SN

mapper.insert:
INSERT INTO EML_CERT (
       EML_CERT_PRPS_CD
     , CERT_TRGT_EML_ENC
     , CERT_TRGT_EML_HMAC
     , CERT_NO_HASH
     , CERT_EXPRY_DT
     , REG_DT
) VALUES (
       #{emlCertPrpsCd}
     , #{certTrgtEmlEnc}
     , #{certTrgtEmlHmac}
     , #{certNoHash}
     , #{certExpryDt}
     , #{regDt}
)

mapper.update:
UPDATE EML_CERT
   SET CERT_INVLD_DT = #{now}
 WHERE CERT_TRGT_EML_HMAC = #{certTrgtEmlHmac}
   AND EML_CERT_PRPS_CD = #{emlCertPrpsCd}
   AND CERT_INVLD_DT IS NULL
   AND CERT_USE_CMPTN_DT IS NULL

UPDATE EML_CERT
   SET CERT_INVLD_DT = #{now}
 WHERE EML_CERT_SN = #{emlCertSn}
   AND CERT_INVLD_DT IS NULL

UPDATE EML_CERT
   SET CERT_FAIL_NMTM = CERT_FAIL_NMTM + 1
 WHERE EML_CERT_SN = #{emlCertSn}

UPDATE EML_CERT
   SET CERT_CMPTN_DT = #{now}
 WHERE EML_CERT_SN = #{emlCertSn}
   AND CERT_CMPTN_DT IS NULL

UPDATE EML_CERT
   SET CERT_USE_CMPTN_DT = #{now}
 WHERE EML_CERT_SN = #{emlCertSn}
   AND CERT_CMPTN_DT IS NOT NULL
   AND CERT_USE_CMPTN_DT IS NULL
